WITH src AS (SELECT * FROM orders WHERE store_id IN (17, 37) OR store_id IS NULL), status_group_summary AS (SELECT CASE WHEN status IN ('PENDING', 'COMPLETED') THEN 'tier_1' ELSE 'other' END AS status_group, SORT_ARRAY(COLLECT_SET(status)) AS status_list, ROUND((100 * SUM(CASE WHEN status = 'COMPLETED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_completed FROM src GROUP BY CASE WHEN status IN ('PENDING', 'COMPLETED') THEN 'tier_1' ELSE 'other' END) SELECT status_group, status_list, pct_completed FROM status_group_summary;
